<script setup>
import {computed,ref,onBeforeUnmount,onMounted} from 'vue'
import Icon from './Icon.vue'
import HelpTip from './HelpTip.vue'
import {call,isDemo} from './service'
const props=defineProps({sessions:Array,rooms:Array,member:Object})
const emit=defineEmits(['refresh','notify'])
const selected=ref(''),messages=ref([]),error=ref(''),busy=ref(false),following=ref(false),privacy=ref('unlisted'),audience=ref(''),lastChecked=ref('')
let timer=null, generation=0
const online=computed(()=>props.sessions.filter(s=>s.mode==='Online'))
const session=computed(()=>online.value.find(s=>s.name===selected.value))
async function action(method,status){error.value='';busy.value=true;try{const result=await call(method,method==='connect'?{}:{session:selected.value,privacy:privacy.value,made_for_kids:audience.value==='kids',status},'youtube');if(method==='connect'){const u=new URL(result);if(u.origin!=='https://accounts.google.com')throw Error('Unexpected OAuth destination');location.assign(result)}else{emit('refresh');emit('notify','YouTube session updated.')}}catch(e){error.value=e.message}finally{busy.value=false}}
function stop(){generation++;following.value=false;clearTimeout(timer)}
async function poll(){if(!following.value)return;const requestGeneration=generation;try{if(document.hidden){timer=setTimeout(poll,15000);return}const response=await call('live_chat',{session:selected.value},'youtube');if(!following.value||requestGeneration!==generation)return;messages.value=response.messages;lastChecked.value=new Date().toLocaleTimeString();if(response.ended){stop();error.value=response.message||'This live chat has ended.'}else timer=setTimeout(poll,Math.max(5000,response.polling_interval_ms||10000))}catch(e){if(requestGeneration!==generation)return;stop();error.value=e.message}}
function start(){stop();error.value='';messages.value=[];following.value=true;poll()}
function change(){stop();messages.value=[];error.value='';lastChecked.value=''}
onMounted(()=>selected.value=online.value.find(s=>s.youtube_id)?.name||online.value[0]?.name||'')
onBeforeUnmount(stop)
</script>
<template><div class="page-heading"><div><div class="eyebrow">YOUR BROADCAST. YOUR CLASSROOM. TOGETHER.</div><h1>Live teaching studio.</h1><p>Manage a YouTube session and read its live chat without leaving your LMS.</p></div><button v-if="member.role==='Teacher'" class="button primary" @click="action('connect')"><Icon name="Youtube" :size="18"/>Connect YouTube</button></div><p v-if="error" class="error" role="alert">{{error}}</p><section class="panel live-controls"><label>Online session<select v-model="selected" @change="change"><option v-for="s in online" :value="s.name">{{rooms.find(r=>r.name===s.classroom)?.subject}} · {{s.title}}</option></select></label><div class="form-row"><label>YouTube visibility <HelpTip text="Public broadcasts can be discovered on YouTube. Unlisted URLs can be shared. Private broadcasts require Google account invitations. LMS payment checks do not override YouTube access rules."/><select v-model="privacy"><option value="unlisted">Unlisted</option><option value="public">Public</option><option value="private">Private</option></select></label><label>Audience for a new broadcast <HelpTip text="Select the correct audience in YouTube. Live chat is not available on content designated Made for kids."/><select v-model="audience"><option value="" disabled>Choose an audience</option><option value="general">Not made for kids</option><option value="kids">Made for kids</option></select></label></div><div class="inline wrap"><button class="button primary" :disabled="busy||!session||!!session.youtube_id||!audience" @click="action('schedule_broadcast')">Create YouTube broadcast</button><button class="button subtle" :disabled="busy||!session?.youtube_id" @click="action('transition_broadcast','live')">Start broadcast</button><button class="button subtle" :disabled="busy||!session?.youtube_id" @click="action('transition_broadcast','complete')">End broadcast</button><a href="https://studio.youtube.com/" target="_blank" rel="noopener noreferrer" class="text-button">Encoder setup in YouTube Studio <Icon name="ArrowUpRight" :size="15"/></a></div><p class="field-help">Your camera feed uses YouTube Studio or an encoder such as OBS. The LMS schedules and controls the broadcast; it does not transmit camera video itself. Visibility and audience above apply when creating a new broadcast.</p></section><div class="live-layout"><section class="panel"><div class="section-heading"><h2>{{session?.title||'Choose an online session'}}</h2><span class="badge violet">{{isDemo?'Recorded playback demo':session?.status}}</span></div><iframe v-if="session?.youtube_id" :src="'https://www.youtube.com/embed/'+session.youtube_id" title="Classroom YouTube broadcast" referrerpolicy="strict-origin-when-cross-origin" allow="encrypted-media; picture-in-picture; fullscreen" allowfullscreen></iframe><div v-else class="empty-state"><Icon name="Video" :size="40"/><p>Create or attach a YouTube broadcast to see its player here.</p></div><p class="field-help">{{isDemo?'This is the supplied stock video, not a live broadcast. Chat on the right is a separate synthetic demonstration.':'Playback and live chat availability follow the channel’s YouTube settings.'}}</p></section><aside class="panel live-chat"><div class="section-heading"><h2>Live chat</h2><span class="badge" :class="following?'green':'violet'">{{isDemo?'Demo comments':following?'Following':'Paused'}}</span></div><div class="inline wrap"><button class="button primary small" :disabled="!session?.youtube_id||following" @click="start">Read comments</button><button class="button subtle small" :disabled="!following" @click="stop">Pause</button></div><p class="field-help">{{isDemo?'Fictional messages, not comments from the supplied video.':'Messages are read through your connected teacher account. Refresh follows YouTube’s polling interval.'}}</p><div class="chat-messages" role="log" aria-live="polite"><article v-for="m in messages" :key="m.id"><span class="teacher-avatar">{{m.author?.[0]||'L'}}</span><div><strong>{{m.author}}</strong><p>{{m.text}}</p><small>{{m.published_at}}</small></div></article><div v-if="!messages.length" class="empty-state"><Icon name="MessageCircle"/><p>Start reading to bring your classroom conversation here.</p></div></div><small v-if="lastChecked" class="field-help">Last checked {{lastChecked}}</small><p class="field-help">Made-for-kids broadcasts, disabled chat, ended sessions and unavailable channel permissions may prevent chat access.</p></aside></div></template>
